rss.channel:

{{ .Site.Title }}
{{ .Site.Params.description }}
{{ .Site.BaseURL }}

{{ site.Language.Locale | default "en" }}
{{ $author := .Site.Params.author }}
Copyright {{ now.Format "2006"}}, {{ $author }}
{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
Hugo - gohugo.io
http://cyber.harvard.edu/rss/rss.html
{{- with .OutputFormats.Get "RSS" }}

{{- end }}
{{ range where .Site.RegularPages "Section" "blog" }}


  {{ .Title }}
  {{ .Permalink }}
  {{- /* Make page-relative and root-relative src/href/poster URLs absolute */ -}}
  {{- $content := replaceRE `(src|href|poster)="/([^/"][^"]*)"` (printf `$1="%s$2"` site.BaseURL) .Content -}}
  {{- $content = replaceRE `(src|href|poster)="([^"#/:?][^":]*)"` (printf `$1="%s$2"` .Permalink) $content }}
  {{ $content | html }}
  {{ .Site.Params.email }} ({{ .Site.Params.author }})
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}

{{ end }}
